select is((select count(*)::int from pg_constraint where contype='x' and conrelid in(to_regclass('public.barbershop_hours'),to_regclass('public.barber_schedules'))),2,'hours exclusions');
select ok(exists(select 1 from pg_constraint where conname='barber_profiles_membership_fkey' and contype='f'),'profile tenant membership FK');
select ok(exists(select 1 from pg_constraint where conname='barber_services_service_fkey' and contype='f'),'capability tenant service FK');
select ok(exists(select 1 from pg_constraint where conname='staff_invitations_one_pending' or conname='unused') or exists(select 1 from pg_indexes where indexname='staff_invitations_one_pending'),'one pending invitation index');
select ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname='check_booking_hours' and p.prosecdef and p.proconfig @> array['search_path=""']),'private trigger fixed search path');
select ok(not coalesce(has_function_privilege('authenticated',to_regprocedure('private.check_booking_hours()'),'EXECUTE'),false),'no direct trigger EXECUTE');
select * from finish();
rollback;
